+// API keys and roles. Keys live in the store as `apiKeys`; each has a role.
+// Roles are ranked: a higher role may do everything a lower one may.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles from least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (text) => createHash("sha256").update(String(text)).digest();
+
+/** The API key record for a key string; throws `unauthorized` when missing or unknown. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || key === "") throw new AppError("unauthorized");
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && k.key !== "" && timingSafeEqual(digest(k.key), wanted)) found ??= k;
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** The role a request needs: the route's own, else viewer to read (GET) and manager for the rest. */
+export function requiredRole(method, routeRole) {
+  return routeRole ?? (method === "GET" ? "viewer" : "manager");
+}
+
+/** Throws `forbidden` unless `role` ranks at least as high as `needed`. */
+export function authorize(role, needed) {
+  const have = ROLES.indexOf(role);
+  const want = ROLES.indexOf(needed);
+  if (have < 0 || want < 0 || have < want) throw new AppError("forbidden", { role: needed });
+}
